@router.get("/webhooks/channels/{channel_pk}")
async def get_notification_channel(
    channel_pk: str,
    current_user: User = Depends(get_current_user)
):
    try:
        channel = NotificationChannel.get(channel_pk)
    except NotFoundError:
        raise HTTPException(status_code=404, detail="Notification channel not found")

    if channel.team_id != current_user.team_id:
        raise HTTPException(status_code=403, detail="Forbidden: access to notification channel secret denied")

    return {
        "channel_pk": channel.pk,
        "destination_url": channel.destination_url,
        "hmac_secret_token": channel.hmac_secret,
        "is_active": channel.is_active
    }
